<script>
(()=>{const project=document.getElementById('project'),c=document.getElementById('category'),t=document.getElementById('type'),title=document.getElementById('drawing-title'),block=document.getElementById('loc-block'),floor=document.getElementById('loc-floor'),loc=document.getElementById('loc-location');let data={},last='',serial=0;const fixed=@json($drawing?->project_id);const base=@json(url('client-control/drawings/locations'));function options(key,values){const el=document.getElementById('list-'+key);el.replaceChildren();for(const v of new Set(values)){const o=document.createElement('option');o.value=v;el.append(o);}}function suggest(){if(!c||!t||!t.value)return;const value=[floor.value,c.selectedOptions[0].text,t.selectedOptions[0].text].filter(Boolean).join(' - ');if(!title.value||title.value===last){title.value=value;last=value;}}function sync(){if(c&&t){for(const o of t.options){if(o.value){o.hidden=o.disabled=o.dataset.category!==c.value;if(o.disabled&&o.selected)t.value='';}}}suggest();}function locations(){const blocks=(data.blocks||[]).filter(x=>x.name===block.value).map(x=>x.id);const floors=(data.floors||[]).filter(x=>!block.value||blocks.includes(x.project_block_id));options('block',(data.blocks||[]).map(x=>x.name));options('floor',floors.map(x=>x.name));const ids=floors.filter(x=>!floor.value||x.name===floor.value).map(x=>x.id);options('location',[...(data.units||[]),...(data.rooms||[]),...(data.subspaces||[])].filter(x=>ids.includes(x.project_floor_id)).map(x=>x.name));suggest();}async function load(){const token=++serial;data={};locations();const id=project?.value||fixed;if(!id)return;try{const response=await fetch(base+'/'+encodeURIComponent(id),{headers:{Accept:'application/json'}});if(!response.ok)throw Error();const result=await response.json();if(token===serial){data=result;locations();}}catch(e){if(token===serial)options('block',[]);}}project?.addEventListener('change',()=>{block.value=floor.value=loc.value='';load();});block.addEventListener('change',()=>{floor.value=loc.value='';locations();});floor.addEventListener('change',()=>{loc.value='';locations();});c?.addEventListener('change',sync);t?.addEventListener('change',suggest);const approval=document.querySelector('[name=client_approval_required]');function due(){document.getElementById('due-wrap').hidden=approval.value!=='1';}approval.addEventListener('change',due);due();sync();load();const file=document.querySelector("[name=file]"),preview=document.getElementById("cad-preview");if(file&&preview){file.addEventListener("change",()=>{preview.hidden=!/\.(dwg|dxf)$/i.test(file.value);if(preview.hidden)preview.querySelector("input").value="";});}})();
</script>
